//! Agents queries: every lookup takes the actor (`find_for(db, &user, id)`), so another user's id is 404. Generated by `cargo offrails generate resource agents name:string description:text`.

use chrono::Utc;
use sea_orm::{ActiveValue::Set, QueryOrder, QuerySelect, entity::prelude::*};

use super::{ActiveModel, Column, Entity, Model, NewAgent};
use crate::error::AppError;
use crate::models::{Page, User};

/// Unscoped. Model-private, so a handler can't compile a lookup that skips the actor.
pub(in crate::models) async fn find(db: &impl ConnectionTrait, id: i64) -> Result<Model, AppError> {
    Entity::find_by_id(id)
        .one(db)
        .await?
        .ok_or(AppError::NotFound)
}

/// For jobs and tasks, which act without a request (their args carry ids).
#[tracing::instrument(skip_all, fields(id))]
pub async fn find_system(db: &impl ConnectionTrait, id: i64) -> Result<Model, AppError> {
    find(db, id).await
}

/// The agent if `user` owns it, else `NotFound` (another user's id looks missing).
#[tracing::instrument(skip_all, fields(id))]
pub async fn find_for(db: &impl ConnectionTrait, user: &User, id: i64) -> Result<Model, AppError> {
    Entity::find_by_id(id)
        .filter(Column::UserId.eq(user.id))
        .one(db)
        .await?
        .ok_or(AppError::NotFound)
}

/// A page of `user`'s agents, newest first, and whether there's another page.
#[tracing::instrument(skip_all)]
pub async fn all_for(
    db: &impl ConnectionTrait,
    user: &User,
    page: Page,
) -> Result<(Vec<Model>, bool), AppError> {
    let per = page.per();
    let mut rows = Entity::find()
        .filter(Column::UserId.eq(user.id))
        .order_by_desc(Column::CreatedAt)
        .order_by_desc(Column::Id)
        .limit(per + 1)
        .offset(page.offset())
        .all(db)
        .await?;
    let more = rows.len() as u64 > per;
    rows.truncate(per as usize);
    Ok((rows, more))
}

/// `user`'s agents for a `<select>`: (id, label), at most 200, by label.
#[tracing::instrument(skip_all)]
pub async fn choices_for(
    db: &impl ConnectionTrait,
    user: &User,
) -> Result<Vec<(i64, String)>, AppError> {
    let rows = Entity::find()
        .filter(Column::UserId.eq(user.id))
        .order_by_desc(Column::Id)
        .limit(200)
        .all(db)
        .await?;
    let mut out: Vec<(i64, String)> = rows.iter().map(|r| (r.id, r.label())).collect();
    out.sort_by(|a, b| a.1.cmp(&b.1));
    Ok(out)
}

/// A new agent owned by `user`.
#[tracing::instrument(skip_all)]
pub async fn create(
    db: &impl ConnectionTrait,
    user: &User,
    new: NewAgent,
) -> Result<Model, AppError> {
    let now = Utc::now();
    ActiveModel {
        user_id: Set(user.id),
        name: Set(new.name),
        description: Set(new.description),
        created_at: Set(now),
        updated_at: Set(now),
        ..Default::default()
    }
    .insert(db)
    .await
    .map_err(AppError::from)
}

/// Saves `user`'s changes to their own agent (`find_for` already scoped it).
#[tracing::instrument(skip_all, fields(id = record.id))]
pub async fn update_for(
    db: &impl ConnectionTrait,
    user: &User,
    record: Model,
    new: NewAgent,
) -> Result<Model, AppError> {
    if record.user_id != user.id {
        return Err(AppError::NotFound);
    }
    let mut am: ActiveModel = record.into();
    am.name = Set(new.name);
    am.description = Set(new.description);
    am.updated_at = Set(Utc::now());
    am.update(db).await.map_err(AppError::from)
}

/// Deletes `user`'s own agent.
#[tracing::instrument(skip_all, fields(id = record.id))]
pub async fn destroy_for(
    db: &impl ConnectionTrait,
    user: &User,
    record: Model,
) -> Result<(), AppError> {
    if record.user_id != user.id {
        return Err(AppError::NotFound);
    }
    if super::super::request::Entity::find()
        .filter(super::super::request::Column::AgentId.eq(record.id))
        .one(db)
        .await?
        .is_some()
    {
        return Err(AppError::Invalid(crate::models::Errors::single(
            "agent",
            "has requests and must be kept for their history",
        )));
    }
    Entity::delete_by_id(record.id).exec(db).await?;
    Ok(())
}
